type DiagramLinkActivationHandler = (event: MouseEvent<HTMLAnchorElement>, href: string) => void;

export function createDiagramLinkActivationHandler(onOpenSource: (href: string) => void): DiagramLinkActivationHandler {
  return (event, href) => {
    if (!isSourceLinkHref(href)) return;
    event.preventDefault();
    onOpenSource(href);
  };
}

export const DIAGRAM_EDGE_COLOR = "var(--diagram-edge)";
const DEFAULT_NODE_SIZE = { height: 144, width: 288 } as const;
const FRAGMENT_NODE_SIZE = { height: 160, width: 448 } as const;
const LIFELINE_NODE_SIZE = { height: 160, width: 224 } as const;
export const DECISION_NODE_SIZE = { height: 48, width: 48 } as const;

function toDecisionNodeData(
  node: Extract<ProjectedComponentStructureNode, { type: "decision" }>,
): DecisionReactFlowNode["data"] {
  return {
    controlLabel: node.title,
    ports: node.control.cases.map(({ id }) => id),
  };
}

export type DiagramReactFlowRenderModel = Readonly<{
  nodes: readonly DiagramReactFlowNode[];
  edges: readonly DiagramReactFlowEdge[];
  edgeTargets?: ReadonlyMap<string, AnnotationTarget>;
}>;

function toCardNodeData(
  node: Readonly<{
    title: string;
    kind?: string;
    description?: string;
    details?: readonly string[];
    links?: DefaultDiagramNode["links"];
  }>,
  onLinkActivate: DiagramLinkActivationHandler,
): CardReactFlowNode["data"] {
  return {
    label: node.title,
    ...(node.kind ? { eyebrow: node.kind } : {}),
    ...(node.description ? { description: node.description } : {}),
    ...(node.details ? { details: node.details } : {}),
    ...(node.links
      ? {
          links: node.links.map((link) => {
            const Icon = isSourceLinkHref(link.href) ? FileCode2 : ExternalLink;

            return {
              href: link.href,
              label: (
                <>
                  <Icon aria-hidden="true" data-icon="inline-start" />
                  <span className="min-w-0 truncate">Open {getDiagramLinkLabel(link)}</span>
                </>
              ),
            };
          }),
        }
      : {}),
    onLinkActivate,
  };
}

function toLifelineNodeData(
  node: LifelineDiagramNode,
  onLinkActivate: DiagramLinkActivationHandler,
  layout?: DiagramLayoutNodeData,
): LifelineReactFlowNode["data"] {
  return {
    node: {
      kind: node.kind,
      title: node.title,
      ...(node.description ? { description: node.description } : {}),
    },
    ...(node.links
      ? {
          links: node.links.map((link) => {
            const Icon = isSourceLinkHref(link.href) ? FileCode2 : ExternalLink;

            return {
              href: link.href,
              label: (
                <>
                  <Icon aria-hidden="true" data-icon="inline-start" />
                  <span className="min-w-0 truncate">Open {getDiagramLinkLabel(link)}</span>
                </>
              ),
            };
          }),
        }
      : {}),
    onLinkActivate,
    ...(layout ? { layout } : {}),
  };
}

type MeasurableDiagramNode = Artifact["diagram"]["graph"]["nodes"][number] | ProjectedComponentStructureNode;

function toMeasurementNode(node: MeasurableDiagramNode, onOpenSource: (href: string) => void): DiagramReactFlowNode {
  const onLinkActivate = createDiagramLinkActivationHandler(onOpenSource);
  const common = {
    id: node.id,
    position: { x: 0, y: 0 },
    draggable: false,
    focusable: false,
    selectable: false,
  } as const;

  if (node.type === "default" || node.type === "non-component") {
    return {
      ...common,
      type: "card",
      data: toCardNodeData(node, onLinkActivate),
      sourcePosition: Position.Right,
      targetPosition: Position.Left,
      style: { opacity: 0, pointerEvents: "none" },
    };
  }

  if (node.type === "decision") {
    return {
      ...common,
      type: "decision",
      data: toDecisionNodeData(node),
      style: { opacity: 0, pointerEvents: "none" },
    };
  }

  if (node.type === "lifeline") {
    return {
      ...common,
      type: "lifeline",
      data: toLifelineNodeData(node, onLinkActivate),
      style: {
        opacity: 0,
        pointerEvents: "none",
        width: LIFELINE_NODE_SIZE.width,
      },
    };
  }

  return {
    ...common,
    type: "fragment",
    data: {
      node: {
        operator: node.operator,
        branches: node.branches.map(({ id, guard }) => ({ id, guard })),
      },
    },
    style: {
      opacity: 0,
      pointerEvents: "none",
      width: FRAGMENT_NODE_SIZE.width,
      height: FRAGMENT_NODE_SIZE.height,
    },
  };
}

export function buildDiagramMeasurementNodes(
  artifact: Artifact,
  onOpenSource: (href: string) => void,
): DiagramReactFlowNode[] {
  return artifact.diagram.graph.nodes.map((node) => toMeasurementNode(node, onOpenSource));
}

/** Measurement nodes for a projected component structure graph: cards, non-component cards, and decision diamonds. */
export function buildComponentStructureMeasurementNodes(
  graph: ProjectedComponentStructureGraph,
  onOpenSource: (href: string) => void,
): DiagramReactFlowNode[] {
  return graph.nodes.map((node) => toMeasurementNode(node, onOpenSource));
}

export function resolveDiagramNodeSizes(
  source:
    | Readonly<{ graph: { nodes: readonly { id: string }[] } }>
    | Readonly<{ nodes: ProjectedComponentStructureGraph["nodes"] }>,
  nodes: readonly Pick<Node, "id" | "measured" | "type">[],
): DiagramNodeSizes {
  const measuredNodeSizes = Object.fromEntries(
    nodes.map((node) => {
      if (node.measured?.width && node.measured.height) {
        return [node.id, { height: node.measured.height, width: node.measured.width }];
      }
      if (node.type === "lifeline") return [node.id, LIFELINE_NODE_SIZE];
      if (node.type === "fragment") return [node.id, FRAGMENT_NODE_SIZE];
      if (node.type === "decision") return [node.id, DECISION_NODE_SIZE];
      return [node.id, DEFAULT_NODE_SIZE];
    }),
  );
  const expectedIds = "graph" in source ? source.graph.nodes.map(({ id }) => id) : source.nodes.map(({ id }) => id);
  const missingId = expectedIds.find((id) => !measuredNodeSizes[id]);
  if (missingId != null) throw new Error(`React Flow did not measure diagram node: ${missingId}`);

  return measuredNodeSizes;
}

function toDiagramReactFlowNodes(
  groups: readonly DiagramGroup[],
  graphNodes: readonly MeasurableDiagramNode[],
  layout: DiagramLayout,
  onOpenSource: (href: string) => void,
  nodesActivatable: boolean,
): DiagramReactFlowNode[] {
  const onLinkActivate = createDiagramLinkActivationHandler(onOpenSource);
  const placedGroups = layout.groups.map<LabeledGroupReactFlowNode>((placement) => {
    const group = groups.find(({ id }) => id === placement.id);
    if (!group) throw new Error(`Layout result references an unknown diagram group: ${placement.id}`);

    return {
      id: group.id,
      type: "labeled-group",
      data: {
        label: group.title,
        ...(group.description ? { description: group.description } : {}),
        ...(nodesActivatable ? { activatable: true } : {}),
      },
      position: placement.position,
      ...(placement.parentId ? { parentId: placement.parentId } : {}),
      style: { width: placement.size.width, height: placement.size.height },
      draggable: false,
      focusable: false,
      selectable: false,
    };
  });
  const nodes = layout.nodes.map<DiagramReactFlowNode>((placement) => {
    const node = graphNodes.find(({ id }) => id === placement.id);
    if (!node) throw new Error(`Layout result references an unknown diagram node: ${placement.id}`);

    const common = {
      id: node.id,
      position: placement.position,
      ...(placement.parentId ? { parentId: placement.parentId } : {}),
      ...(placement.size ? { style: { width: placement.size.width, height: placement.size.height } } : {}),
      draggable: false,
      focusable: false,
      selectable: false,
    } as const;

    if (node.type === "default" || node.type === "non-component") {
      return {
        ...common,
        type: "card",
        data: {
          ...toCardNodeData(node, onLinkActivate),
          ...(nodesActivatable ? { activatable: true } : {}),
        },
        sourcePosition: Position.Right,
        targetPosition: Position.Left,
      };
    }

    if (node.type === "decision") {
      return {
        ...common,
        type: "decision",
        data: toDecisionNodeData(node),
      };
    }

    const layoutData = placement.data;
    if (node.type === "lifeline") {
      return {
        ...common,
        type: "lifeline",
        data: toLifelineNodeData(node, onLinkActivate, layoutData),
      };
    }

    return {
      ...common,
      type: "fragment",
      data: {
        node: {
          operator: node.operator,
          branches: node.branches.map(({ id, guard }) => ({ id, guard })),
        },
        ...(layoutData ? { layout: layoutData } : {}),
      },
    };
  });
  return [...placedGroups, ...nodes];
}

export function buildDiagramReactFlowNodes(
  artifact: Artifact,
  layout: DiagramLayout,
  onOpenSource: (href: string) => void,
  nodesActivatable = false,
): DiagramReactFlowNode[] {
  return toDiagramReactFlowNodes(
    artifact.diagram.graph.groups,
    artifact.diagram.graph.nodes,
    layout,
    onOpenSource,
    nodesActivatable,
  );
}

/** Placed nodes for a projected component structure graph, including its decision diamonds and non-component cards. */
export function buildComponentStructureReactFlowNodes(
  graph: ProjectedComponentStructureGraph,
  layout: DiagramLayout,
  onOpenSource: (href: string) => void,
): DiagramReactFlowNode[] {
  return toDiagramReactFlowNodes(graph.groups, graph.nodes, layout, onOpenSource, false);
}

export function toMessageReactFlowEdge(
  edge: MessageDiagramEdge,
  points: readonly DiagramLayoutPoint[],
  onLinkActivate: DiagramLinkActivationHandler,
): MessageReactFlowEdge {
  return {
    id: edge.id,
    source: edge.source,
    target: edge.target,
    focusable: false,
    selectable: false,
    markerEnd: {
      type: edge.messageType === "sync" ? MarkerType.ArrowClosed : MarkerType.Arrow,
      color: DIAGRAM_EDGE_COLOR,
    },
    style: {
      stroke: DIAGRAM_EDGE_COLOR,
      strokeWidth: 2,
      ...(edge.messageType === "return" ? { strokeDasharray: "6 4" } : {}),
    },
    type: "message",
    sourceHandle: `${edge.id}:source`,
    targetHandle: `${edge.id}:target`,
    zIndex: 1,
    data: {
      edge: {
        source: edge.source,
        target: edge.target,
        ...(edge.kind ? { kind: edge.kind } : {}),
        ...(edge.label ? { label: edge.label } : {}),
        ...(edge.href ? { href: edge.href } : {}),
        messageType: edge.messageType,
      },
      points,
      onLinkActivate,
    },
  };
}
